mapper.sql:
WHERE d.deleted = FALSE

    AND (d.demand_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR d.demand_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR d.description ILIKE #{q.keywordLike} ESCAPE '\')


    AND d.domain_code = #{q.domainCode}


    AND d.review_state = #{q.reviewState}


    AND d.outlet = #{q.outlet}



    AND d.solution_state = #{q.solutionState}


    AND d.dev_state = #{q.devState}


    AND d.acceptance_state = #{q.acceptanceState}


    AND d.owner_no = #{q.ownerNo}


    AND d.proposed_date >= #{q.proposedFrom}


    AND d.proposed_date <= #{q.proposedTo}


    AND d.expect_finish_date >= #{q.expectFinishFrom}


    AND d.expect_finish_date <= #{q.expectFinishTo}




            AND EXISTS (SELECT 1 FROM rel_demand_course rc WHERE rc.demand_id = d.id)


            AND NOT EXISTS (SELECT 1 FROM rel_demand_course rc WHERE rc.demand_id = d.id)





    AND calc_light(
          d.expect_finish_date,
          d.last_state_changed_at,
          (SELECT t.blue_days FROM cfg_warning_threshold t
            WHERE t.object_type = 'AI需求' AND t.deleted = FALSE),
          (SELECT t.red_days FROM cfg_warning_threshold t
            WHERE t.object_type = 'AI需求' AND t.deleted = FALSE),
          d.delivery_mark = '已归档' OR d.outlet = '需求驳回'
        ) = #{q.light}
